#include "dlaa/algorithms.hpp"
#include <algorithm>
#include <cmath>
#include <functional>
#include <stdexcept>
namespace dlaa::algo {
int knapsack01(const std::vector<int>&w,const std::vector<int>&v,int cap){if(w.size()!=v.size()||cap<0)throw std::invalid_argument("knapsack args");std::vector<int>d(cap+1);for(std::size_t i=0;i<w.size();++i){if(w[i]<0)throw std::invalid_argument("negative weight");for(int c=cap;c>=w[i];--c)d[c]=std::max(d[c],d[c-w[i]]+v[i]);}return d[cap];}
int knapsackBacktracking(const std::vector<int>&w,const std::vector<int>&v,int cap){if(w.size()!=v.size()||cap<0)throw std::invalid_argument("knapsack args");int best=0;std::function<void(int,int,int)>go=[&](int i,int cw,int cv){if(i==(int)w.size()){best=std::max(best,cv);return;}go(i+1,cw,cv);if(w[i]>=0&&cw+w[i]<=cap)go(i+1,cw+w[i],cv+v[i]);};go(0,0,0);return best;}
int knapsackBranchBound(const std::vector<int>&w,const std::vector<int>&v,int cap,int strategy){if(w.size()!=v.size()||cap<0)throw std::invalid_argument("knapsack args");struct N{int i,wt,val;double b;};std::vector<int>ord(w.size());for(int i=0;i<(int)w.size();++i){if(w[i]<0)throw std::invalid_argument("negative weight");ord[i]=i;}std::sort(ord.begin(),ord.end(),[&](int a,int b){return (double)v[a]/std::max(1,w[a])>(double)v[b]/std::max(1,w[b]);});std::vector<int>sw,sv;for(int i:ord){sw.push_back(w[i]);sv.push_back(v[i]);}auto bound=[&](int i,int wt,int val){double b=val;int rem=cap-wt;while(i<(int)sw.size()&&rem>0){if(sw[i]<=rem){rem-=sw[i];b+=sv[i++];}else{b+=(double)sv[i]*rem/sw[i];break;}}return b;};std::vector<N>q{{0,0,0,bound(0,0,0)}};int best=0;while(!q.empty()){int k=0;if(strategy==1)k=(int)q.size()-1;else if(strategy==2)for(int j=1;j<(int)q.size();++j)if(q[j].b>q[k].b)k=j;N n=q[k];q.erase(q.begin()+k);if(n.b<=best||n.i==(int)sw.size())continue;q.push_back({n.i+1,n.wt,n.val,bound(n.i+1,n.wt,n.val)});int wt=n.wt+sw[n.i],val=n.val+sv[n.i];if(wt<=cap){best=std::max(best,val);double b=bound(n.i+1,wt,val);if(b>best)q.push_back({n.i+1,wt,val,b});}}return best;}
std::vector<int>nQueens(int n){if(n<1||n>15)throw std::invalid_argument("N must be 1..15");std::vector<int>p(n,-1);std::function<bool(int)>go=[&](int r){if(r==n)return true;for(int c=0;c<n;++c){bool ok=true;for(int i=0;i<r;++i)if(p[i]==c||std::abs(p[i]-c)==r-i){ok=false;break;}if(ok){p[r]=c;if(go(r+1))return true;}}return false;};if(!go(0))return {};return p;}
static long long egcd(long long a,long long b,long long&x,long long&y){if(!b){x=1;y=0;return a;}long long u,v,g=egcd(b,a%b,u,v);x=v;y=u-a/b*v;return g;}
long long chineseRemainder(const std::vector<long long>&a,const std::vector<long long>&m){if(a.empty()||a.size()!=m.size())throw std::invalid_argument("CRT arrays");long long prod=1;for(auto z:m){if(z<=1)throw std::invalid_argument("modulus");for(long long p=2;p*p<=z;++p)if(z%p==0)throw std::invalid_argument("prime moduli required");prod*=z;}long long ans=0;for(std::size_t i=0;i<a.size();++i){long long part=prod/m[i],x,y;egcd(part,m[i],x,y);ans=(ans+((a[i]%m[i]+m[i])%m[i])*part*((x%m[i]+m[i])%m[i]))%prod;}return (ans+prod)%prod;}
}